#!/usr/bin/env Rscript
# make_supp_tables.R -- write manuscript/supp_tables.tex (LaTeX macros holding
# tables built from results/tables/*.csv). Generated; do not edit by hand.
suppressPackageStartupMessages({ library(dplyr); library(tidyr) })
source(file.path(Sys.getenv("MHW_ROOT", unset = "."), "R", "load_all.R"))
tabs <- CFG$dir_tables; out <- file.path(CFG$root, "manuscript", "supp_tables.tex")

lab <- c(naive_glm = "Naive NB GLM", glm_lag1 = "Lag-1 NB GLM", gam = "NB GAM",
         dlnm = "DLNM", sdmtmb = "sdmTMB", rf = "Random forest")
reg <- c(WA = "Western Australia", NW_Atl = "Northwest Atlantic", Med = "Mediterranean")
f <- function(x, d = 3) ifelse(is.finite(x), formatC(x, format = "f", digits = d), "--")
esc <- function(s) gsub("%", "\\\\%", s)

tabular <- function(df, align, caption, label, header = NULL, size = "\\small") {
  if (is.null(header)) header <- names(df)
  body <- apply(df, 1, function(r) paste(r, collapse = " & "))
  c(sprintf("\\begin{table}[H]\\centering\\caption{%s}\\label{%s}%s\\setlength{\\tabcolsep}{4pt}", caption, label, size),
    sprintf("\\begin{tabular}{%s}\\toprule", align),
    paste(header, collapse = " & "), "\\\\\\midrule",
    paste0(body, " \\\\"), "\\bottomrule\\end{tabular}\\end{table}")
}
wrap <- function(name, lines) c(sprintf("\\newcommand{\\%s}{%%", name), lines, "}")

L <- c("% supp_tables.tex -- GENERATED by scripts/make_supp_tables.R")

# -- detection reference ------------------------------------------------------
dr <- read.csv(file.path(tabs, "detection_reference.csv"), stringsAsFactors = FALSE)
d <- data.frame(reg[dr$region], dr$date_start, dr$date_end, dr$duration, f(dr$intensity_max, 2),
                f(dr$intensity_mean, 2), f(dr$intensity_cumulative, 1), dr$n_events)
L <- c(L, wrap("detectionReferenceTable", tabular(d, "lllrrrrr",
  "Most intense event by peak anomaly in each OISST series under the Hobday defaults (1983 to 2012 climatology, 90th percentile, 5 day minimum, 2 day gap). Intensities in $^{\\circ}$C relative to climatology; cumulative intensity in $^{\\circ}$C days.",
  "tab:detref", c("Region", "Start", "End", "Days", "Max", "Mean", "Cumulative", "Events in series"))))

# -- detection sensitivity ----------------------------------------------------
ds <- read.csv(file.path(tabs, "detection_sensitivity_WA2011.csv"), stringsAsFactors = FALSE)
d <- data.frame(gsub("_", " to ", ds$baseline), ds$pctile, ds$date_start, ds$date_end, ds$duration,
                f(ds$intensity_max, 2), f(ds$intensity_mean, 2), f(ds$intensity_cumulative, 1))
L <- c(L, wrap("detectionSensitivityTable", tabular(d, "lrllrrrr",
  "Largest 2011 event by peak anomaly in the Western Australian series under alternative climatology windows and percentile thresholds.",
  "tab:detsens", c("Climatology", "Percentile", "Start", "End", "Days", "Max", "Mean", "Cumulative"))))

# -- DGP calibration ----------------------------------------------------------
dg <- read.csv(file.path(tabs, "dgp_calibration.csv"), stringsAsFactors = FALSE)
d <- data.frame(reg[dg$region], dg$n_sites, dg$true_beta1, dg$true_lag, f(100 * dg$zero_frac, 0),
                f(dg$mean_y, 1), dg$max_y, dg$n_unique, ifelse(dg$usable, "yes", "no"))
L <- c(L, c("\\newcommand{\\dgpCalibrationTable}{%",
  "\\begin{longtable}{llrrrrrrl}",
  "\\caption{Realised response distribution by region, grid size, true effect and true lag (range 50 km, replicate 1).}\\label{tab:dgp}\\\\",
  "\\toprule Region & Sites & $\\beta_1$ & Lag & Zeros (\\%) & Mean $y$ & Max $y$ & Distinct & Usable \\\\\\midrule\\endfirsthead",
  "\\toprule Region & Sites & $\\beta_1$ & Lag & Zeros (\\%) & Mean $y$ & Max $y$ & Distinct & Usable \\\\\\midrule\\endhead",
  paste0(apply(d, 1, paste, collapse = " & "), " \\\\"), "\\bottomrule\\end{longtable}}"))

# -- model summary ------------------------------------------------------------
ms <- read.csv(file.path(tabs, "R_model_summary.csv"), stringsAsFactors = FALSE)
ms <- ms[match(intersect(names(lab), ms$model_id), ms$model_id), ]
d <- data.frame(lab[ms$model_id], ms$n_scenarios, f(ms$mean_bias), f(ms$median_rmse), f(ms$mean_coverage, 2),
                f(ms$mean_logscore, 2), f(ms$mean_morans_I, 3), f(ms$pct_converged, 1), f(ms$median_runtime, 2))
L <- c(L, wrap("modelSummaryTable", tabular(d, "lrrrrrrrr",
  "Model level performance across all scenarios. Coverage is the mean empirical coverage of nominal 95\\% intervals over scenarios where an interval is defined; log score is the mean held out negative binomial log predictive density; Moran's $I$ is the mean residual spatial autocorrelation of site mean residuals.",
  "tab:modsum", c("Model", "Scenarios", "Mean bias", "Median RMSE", "Coverage", "Log score", "Moran's $I$", "Conv. (\\%)", "Median s"), size = "\\footnotesize")))

# -- bias by lag --------------------------------------------------------------
bl <- read.csv(file.path(tabs, "R_bias_by_lag.csv"), stringsAsFactors = FALSE)
bl <- bl %>% mutate(model = lab[model_id]) %>% arrange(match(model_id, names(lab)), true_lag)
d <- data.frame(bl$model, bl$true_lag, f(bl$bias_mean), f(bl$bias_median), f(bl$rmse), f(bl$ci_coverage, 2))
L <- c(L, wrap("biasByLagTable", tabular(d, "lrrrrr",
  "Bias, RMSE and interval coverage by model class and true lag, averaged over regions, effect sizes, spatial ranges and grid sizes.",
  "tab:biaslag", c("Model", "True lag", "Mean bias", "Median bias", "RMSE", "Coverage"))))

# -- relative bias ------------------------------------------------------------
rb <- read.csv(file.path(tabs, "R_relative_bias.csv"), stringsAsFactors = FALSE) %>%
  mutate(model = lab[model_id]) %>% arrange(match(model_id, names(lab)), true_beta1, true_lag)
w <- rb %>% dplyr::select(model, true_beta1, true_lag, rel_bias_pct) %>%
  pivot_wider(names_from = true_lag, values_from = rel_bias_pct, names_prefix = "lag")
d <- data.frame(w$model, w$true_beta1, f(w$lag0, 0), f(w$lag1, 0), f(w$lag2, 0))
L <- c(L, wrap("relativeBiasTable", tabular(d, "lrrrr",
  "Relative bias (\\%) of the estimated exposure coefficient, $100(\\hat\\beta_1-\\beta_1)/\\beta_1$, by model class, true effect and true lag. Negative values indicate under estimation of the magnitude of a negative effect.",
  "tab:relbias", c("Model", "$\\beta_1$", "Lag 0", "Lag 1", "Lag 2"))))

# -- bias by region -----------------------------------------------------------
br <- read.csv(file.path(tabs, "R_bias_by_region.csv"), stringsAsFactors = FALSE) %>%
  mutate(model = lab[model_id], region = reg[region]) %>% arrange(match(model_id, names(lab)), region)
d <- data.frame(br$model, br$region, f(br$bias_mean), f(br$rmse), f(br$ci_coverage, 2))
L <- c(L, wrap("biasByRegionTable", tabular(d, "llrrr",
  "Bias, RMSE and coverage by model class and region.", "tab:biasregion",
  c("Model", "Region", "Mean bias", "RMSE", "Coverage"))))

# -- geometry -----------------------------------------------------------------
bn <- read.csv(file.path(tabs, "R_bias_by_nsites.csv"), stringsAsFactors = FALSE) %>% mutate(fac = paste(n_sites, "sites"))
bs <- read.csv(file.path(tabs, "R_bias_by_range.csv"), stringsAsFactors = FALSE) %>% mutate(fac = paste("range", spatial_range_km, "km"))
bg <- bind_rows(bn %>% dplyr::select(model_id, fac, bias_mean, rmse, ci_coverage),
                bs %>% dplyr::select(model_id, fac, bias_mean, rmse, ci_coverage)) %>%
  mutate(model = lab[model_id]) %>% arrange(match(model_id, names(lab)), fac)
d <- data.frame(bg$model, bg$fac, f(bg$bias_mean), f(bg$rmse), f(bg$ci_coverage, 2))
L <- c(L, wrap("biasByGeometryTable", tabular(d, "llrrr",
  "Bias, RMSE and coverage by model class, grid size and spatial correlation range.", "tab:biasgeom",
  c("Model", "Factor level", "Mean bias", "RMSE", "Coverage"))))

# -- run report ---------------------------------------------------------------
raw <- read.csv(file.path(tabs, "R_raw_results.csv"), stringsAsFactors = FALSE) %>% filter(!is.na(model_id))
rr <- raw %>% group_by(model_id) %>%
  summarise(n = n(), est = 100 * mean(is.finite(beta1_hat)), ci = 100 * mean(is.finite(beta1_lo)),
            conv = 100 * mean(converged), sec = median(runtime_sec), .groups = "drop") %>%
  arrange(match(model_id, names(lab)))
d <- data.frame(lab[rr$model_id], rr$n, f(rr$est, 1), f(rr$ci, 1), f(rr$conv, 1), f(rr$sec, 2))
L <- c(L, wrap("runReportTable", tabular(d, "lrrrrr",
  "Run report: number of fits, percentage returning a point estimate, percentage returning an interval, percentage passing the package's convergence check, and median wall clock time per fit.",
  "tab:runreport", c("Model", "Fits", "Estimate (\\%)", "Interval (\\%)", "Converged (\\%)", "Median s"))))


writeLines(L, out); mhw_log("wrote %s", out)
